{
	iw_byte b;
	int token_len = 0;
	int linepos;

	token_len = 0;

	linepos = *curpos;
	while(1) {
		if(token_len >= tokenbuflen) {
			// Token too long.
			return 0;
		}

		b = linebuf[linepos++];
		if(b==0) break; // End of line

		if(iwpnm_is_whitespace(b)) {
			if(token_len>0) {
				break;
			}
			else {
				// Skip leading whitespace.
				continue;
			}
		}
		else {
			// Append the character to the token.
			tokenbuf[token_len] = b;
			token_len++;
		}
	}

	tokenbuf[token_len] = '\0';
	*curpos = linepos;
	return 1;
}

